INSERT INTO "Department" ("id", "name", "shortName", "description", "ministerName", "secretaryName", "headName", "contactEmail", "contactPhone", "address", "website", "services", "budgetInrCr", "officialSource", "sourceName", "lastVerifiedAt", "verificationStatus", "verificationNote") VALUES
  ('cmw53odd300xgu310ic9078zp', 'Department of Health and Family Welfare', 'Health', 'Delivers public health services, the hospital network, disease control and the Chief Minister’s Comprehensive Health Insurance implementation across Tamil Nadu.', 'Dr. K. G. Arunraj', NULL, NULL, NULL, NULL, NULL, 'https://www.tnhealth.tn.gov.in', NULL, 18000, 'https://www.tnhealth.tn.gov.in', 'Government of Tamil Nadu — official department page', '2026-11-05T06:00:00.000Z', 'VERIFIED', 'Minister verified against the official Council of Ministers list (tn.gov.in) on 2026-11-05. Demonstration figure — 2026-27 departmental allocation pending verification against official budget documents. Departmental secretary postings pending official confirmation.'),
  ('cmw53odd400xhu310jfy6ee30', 'Department of School Education', 'School Edu', 'Runs government and aided schools, teacher management, mid-day meals and the Perunthalaivar Kamarajar Breakfast Scheme (expanded to Classes VI–VIII in September 2026).', 'Rajmohan Arumugam', NULL, NULL, NULL, NULL, NULL, 'https://www.tn.gov.in/dept/school', NULL, 44527, 'https://www.tn.gov.in/dept/school', 'Government of Tamil Nadu — official department page', '2026-11-05T06:00:00.000Z', 'VERIFIED', 'Minister verified against the official Council of Ministers list (tn.gov.in) on 2026-11-05. ₹44,527 crore allocated for school education in the 2026-27 budget (presented 5 Aug 2026). Departmental secretary postings pending official confirmation.'),
  ('cmw53odd500xiu31056fhq7zo', 'Finance Department', 'Finance', 'Prepares the state budget, expenditure control, treasury administration and the Human Resources Management wing. Presented the maiden budget of the 17th Assembly government on 5 Aug 2026 (total expenditure ₹4,72,585 crore); a white paper on the state’s financial position has been announced.', 'Dr. N. Marie Wilson', NULL, NULL, NULL, NULL, NULL, 'https://financedept.tn.gov.in', NULL, 472585, 'https://financedept.tn.gov.in', 'Government of Tamil Nadu — official department page', '2026-11-05T06:00:00.000Z', 'VERIFIED', 'Minister verified against the official Council of Ministers list (tn.gov.in) on 2026-11-05. Figure shown is the state total expenditure estimate for 2026-27, as cited by PRS Legislative Research from the budget documents. Departmental secretary postings pending official confirmation.'),
  ('cmw53odd500xju310a1muycvi', 'Public Works Department', 'PWD', 'Buildings, highways and minor ports; maintains state buildings, state-highway roads and the Kudimaramathu waterbody restoration works. Sports Development is allocated alongside Public Works.', 'Aadhav Arjuna', NULL, NULL, NULL, NULL, NULL, 'https://www.tn.gov.in/dept/pwd', NULL, 12500, 'https://www.tn.gov.in/dept/pwd', 'Government of Tamil Nadu — official department page', '2026-11-05T06:00:00.000Z', 'VERIFIED', 'Minister verified against the official Council of Ministers list (tn.gov.in) on 2026-11-05. Demonstration figure — 2026-27 departmental allocation pending verification against official budget documents. Departmental secretary postings pending official confirmation.'),
  ('cmw53odd600xku310535fxuw9', 'Rural Development and Panchayat Raj Department', 'RDPR', 'Village panchayat governance, MGNREGS employment guarantee and the Kalaignar Magalir Urimai Thogai disbursement machinery; Water Resources is allocated alongside Rural Development.', 'N. Anand', NULL, NULL, NULL, NULL, NULL, 'https://www.tn.gov.in/dept/rd', NULL, 25000, 'https://www.tn.gov.in/dept/rd', 'Government of Tamil Nadu — official department page', '2026-11-05T06:00:00.000Z', 'VERIFIED', 'Minister verified against the official Council of Ministers list (tn.gov.in) on 2026-11-05. Demonstration figure — 2026-27 departmental allocation pending verification against official budget documents. Departmental secretary postings pending official confirmation.'),
  ('cmw53odd700xlu310xsgsrupc', 'Revenue and Disaster Management Department', 'Revenue', 'Land administration, revenue records, disaster preparedness, relief distribution and district revenue machinery.', 'K. A. Sengottaiyan', NULL, NULL, NULL, NULL, NULL, 'https://www.tn.gov.in/dept/revenue', NULL, 9000, 'https://www.tn.gov.in/dept/revenue', 'Government of Tamil Nadu — official department page', '2026-11-05T06:00:00.000Z', 'VERIFIED', 'Minister verified against the official Council of Ministers list (tn.gov.in) on 2026-11-05. Demonstration figure — 2026-27 departmental allocation pending verification against official budget documents. Departmental secretary postings pending official confirmation.'),
  ('cmw53odd700xmu310309m5epc', 'Municipal Administration and Water Supply Department', 'MAWS', 'Urban local bodies governance, city corporations, drinking water supply schemes and underground sewerage programmes. Held personally by the Chief Minister in the current portfolio allocation.', 'C. Joseph Vijay', NULL, NULL, NULL, NULL, NULL, 'https://www.tn.gov.in/dept/maws', NULL, 15000, 'https://www.tn.gov.in/dept/maws', 'Government of Tamil Nadu — official department page', '2026-11-05T06:00:00.000Z', 'VERIFIED', 'Minister verified against the official Council of Ministers list (tn.gov.in) on 2026-11-05. Demonstration figure — 2026-27 departmental allocation pending verification against official budget documents. Departmental secretary postings pending official confirmation.'),
  ('cmw53odd800xnu3106hqld57c', 'Transport Department', 'Transport', 'State transport undertakings, motor vehicles regulation, road safety initiatives and concessionary travel programmes (fare-free city-bus travel for women reported continuing under the new government — status pending official confirmation).', 'Vijay Tamilan Parthiban', NULL, NULL, NULL, NULL, NULL, 'https://www.tn.gov.in/dept/transport', NULL, 5500, 'https://www.tn.gov.in/dept/transport', 'Government of Tamil Nadu — official department page', '2026-11-05T06:00:00.000Z', 'VERIFIED', 'Minister verified against the official Council of Ministers list (tn.gov.in) on 2026-11-05. Demonstration figure — 2026-27 departmental allocation pending verification against official budget documents. Departmental secretary postings pending official confirmation.'),
  ('cmw53odd800xou310p1xnlz8x', 'Agriculture and Farmers’ Welfare Department', 'Agriculture', 'Crop development, input subsidies, farm mechanisation and climate-resilient agriculture programmes.', 'R. Vinoth', NULL, NULL, NULL, NULL, NULL, 'https://www.tn.gov.in/dept/agri', NULL, 22000, 'https://www.tn.gov.in/dept/agri', 'Government of Tamil Nadu — official department page', '2026-11-05T06:00:00.000Z', 'VERIFIED', 'Minister verified against the official Council of Ministers list (tn.gov.in) on 2026-11-05. Demonstration figure — 2026-27 departmental allocation pending verification against official budget documents. Departmental secretary postings pending official confirmation.'),
  ('cmw53odd900xpu31024f3c2bt', 'Home, Prohibition and Excise Department', 'Home', 'Police administration, fire and rescue services, prisons and prohibition enforcement. Held personally by the Chief Minister, who retained Public, General Administration, Police and welfare portfolios in the May 2026 allocation.', 'C. Joseph Vijay', NULL, NULL, NULL, NULL, NULL, 'https://www.tn.gov.in/dept/home', NULL, 14000, 'https://www.tn.gov.in/dept/home', 'Government of Tamil Nadu — official department page', '2026-11-05T06:00:00.000Z', 'VERIFIED', 'Minister verified against the official Council of Ministers list (tn.gov.in) on 2026-11-05. Demonstration figure — 2026-27 departmental allocation pending verification against official budget documents. Departmental secretary postings pending official confirmation.')
INSERT INTO "Scheme" ("id", "name", "level", "departmentId", "description", "eligibility", "benefits", "beneficiaries", "launchDate", "status", "budgetInrCr", "applicationProcess", "applicationUrl", "documentsRequired", "guidelinesUrl", "officialSource", "sourceName", "lastVerifiedAt", "verifiedBy", "verificationStatus", "verificationNote", "naturalKey") VALUES
  ('cmw53odgm014fu310pig40e72', 'Kalaignar Magalir Urimai Thogai', 'TN', 'cmw53odd600xku310535fxuw9', 'Monthly basic income assistance to eligible women heads of households. In December 2025 the programme was expanded by about 13–17 lakh women, taking coverage to roughly 1.31 crore beneficiaries; the 2026-27 allocation was reported at ₹13,807 crore. The new government announced (May 2026) an intent to raise the assistance to ₹1,500 in phases — not yet implemented as of this verification.', 'Eligible women heads of family meeting income and other criteria as notified.', '₹1,000 per month paid directly to bank accounts (proposed increase to ₹1,500 pending official orders).', 'About 1.31 crore women (Dec 2025 expansion; figures as reported by official statements and The Hindu/dtnext).', '2023-09-15T00:00:00.000Z', 'UPDATED', 13807, 'As per the department’s notified procedure — follow the official source link.', 'https://www.tn.gov.in/dept/rd', 'Per scheme guidelines — confirm on the official application portal.', 'https://www.tn.gov.in/dept/rd', 'https://www.tn.gov.in/dept/rd', 'RDPR Department / TN Budget 2025-26 (revised)', '2026-11-05T06:00:00.000Z', 'civic-lenz-web-verification', 'VERIFIED', 'Beneficiaries aged 60+ are being migrated to the Old Age Pension scheme (May 2026 announcements) to raise their monthly assistance.', 'scheme:kmut'),
  ('cmw53odgn014hu310663i5yyk', 'Perunthalaivar Kamarajar Breakfast Scheme', 'TN', 'cmw53odd400xhu310jfy6ee30', 'Free nutritious breakfast on school working days for government-school students. Retained and renamed under the new government: on 22 Sep 2026 CM C. Joseph Vijay launched its expansion to Classes VI–VIII (earlier Classes I–V), adding about 15.30 lakh students.', 'Students of Classes I–VIII in government schools.', 'Hot cooked breakfast each working day.', 'About 15.30 lakh additional students from the September 2026 expansion (official launch coverage).', '2022-09-15T00:00:00.000Z', 'UPDATED', 700, 'As per the department’s notified procedure — follow the official source link.', 'https://www.tn.gov.in/press-releases', 'Per scheme guidelines — confirm on the official application portal.', 'https://www.tn.gov.in/press-releases', 'https://www.tn.gov.in/press-releases', 'Government of Tamil Nadu — launch coverage (The Hindu, Deccan Herald: 22 Sep 2026)', '2026-11-05T06:00:00.000Z', 'civic-lenz-web-verification', 'VERIFIED', 'Renamed from "Chief Minister’s Breakfast Scheme"; expansion announced at the 22 Sep 2026 official launch.', 'scheme:breakfast'),
  ('cmw53odgo014ju310xzk22m3d', 'Makkalai Thedi Maruthuvam', 'TN', 'cmw53odd300xgu310ic9078zp', 'Doorstep delivery of primary healthcare services including screening for hypertension and diabetes. Continuation under the 17th Assembly government is reported by secondary sources (Oct 2026) but awaits confirmation from an official department communique.', 'Households in all districts, priority to elderly and those with comorbidities.', 'Home visits by health workers, free medicines and follow-up.', 'Over 1 crore beneficiaries (launch-era figure, pending re-verification).', '2021-08-05T00:00:00.000Z', 'ACTIVE', 900, 'As per the department’s notified procedure — follow the official source link.', 'https://www.tn.gov.in/dept/health', 'Per scheme guidelines — confirm on the official application portal.', 'https://www.tn.gov.in/dept/health', 'https://www.tn.gov.in/dept/health', 'Health & Family Welfare Department (official confirmation awaited)', '2026-11-05T06:00:00.000Z', 'civic-lenz-web-verification', 'PENDING_VERIFICATION', NULL, 'scheme:mtm'),
  ('cmw53odgp014lu310nurv4y9z', 'Naan Mudhalvan', 'TN', 'cmw53odd400xhu310jfy6ee30', 'Skill development and career guidance platform for students and youth. Reported ongoing in 2026; one secondary source indicates rebranding towards a state "Skill Development" platform — official confirmation pending.', 'Students of Classes 9–12, college students and job-seeking youth.', 'Free training, career counselling, placement support.', 'Students across all 38 districts (launch-era figure, pending re-verification).', '2022-03-01T00:00:00.000Z', 'ACTIVE', 450, 'As per the department’s notified procedure — follow the official source link.', 'https://www.tn.gov.in/dept/higher', 'Per scheme guidelines — confirm on the official application portal.', 'https://www.tn.gov.in/dept/higher', 'https://www.tn.gov.in/dept/higher', 'Higher Education Department (official confirmation awaited)', '2026-11-05T06:00:00.000Z', 'civic-lenz-web-verification', 'PENDING_VERIFICATION', NULL, 'scheme:naan-mudhalvan'),
  ('cmw53odgr014nu310xedciza0', 'Pudhumai Penn Scheme', 'TN', 'cmw53odd400xhu310jfy6ee30', 'Support for girl students who studied in government schools to pursue higher education. Status under the new government pending official confirmation.', 'Girl students from government schools joining higher education.', '₹1,000 per month until graduation (as notified at launch).', 'Over 1.9 lakh students (launch-era figure, pending re-verification).', '2022-09-05T00:00:00.000Z', 'ACTIVE', 280, 'As per the department’s notified procedure — follow the official source link.', 'https://www.tn.gov.in/dept/school', 'Per scheme guidelines — confirm on the official application portal.', 'https://www.tn.gov.in/dept/school', 'https://www.tn.gov.in/dept/school', 'School Education Department (official confirmation awaited)', '2026-11-05T06:00:00.000Z', 'civic-lenz-web-verification', 'PENDING_VERIFICATION', NULL, 'scheme:pudhumai-penn'),
  ('cmw53odgr014pu310t34h6qj4', 'Fare-free city bus travel for women', 'TN', 'cmw53odd800xnu3106hqld57c', 'Zero-ticket travel for women in ordinary city and town buses operated by state transport undertakings. Continuation under the new government is not yet confirmed from official sources — flagged pending verification.', 'All women commuters in eligible bus services.', 'Zero-ticket travel with monthly trip caps (as notified at launch).', 'Cumulative trips since 2021 in the hundreds of crores (launch-era figure, pending re-verification).', '2021-05-08T00:00:00.000Z', 'ACTIVE', 1600, 'As per the department’s notified procedure — follow the official source link.', 'https://www.tn.gov.in/dept/transport', 'Per scheme guidelines — confirm on the official application portal.', 'https://www.tn.gov.in/dept/transport', 'https://www.tn.gov.in/dept/transport', 'Transport Department (official confirmation awaited)', '2026-11-05T06:00:00.000Z', 'civic-lenz-web-verification', 'PENDING_VERIFICATION', NULL, 'scheme:zero-ticket'),
  ('cmw53odgt014ru310twwo8lkv', 'Illam Thedi Kalvi', 'TN', 'cmw53odd400xhu310jfy6ee30', 'Home-based remedial education volunteer programme to bridge learning loss. Status under the new government pending official confirmation.', 'Students of Classes 1–8 in all districts.', 'Evening volunteer-led learning sessions near residences.', 'About 35 lakh students (launch-era figure, pending re-verification).', '2021-10-11T00:00:00.000Z', 'ACTIVE', 200, 'As per the department’s notified procedure — follow the official source link.', 'https://www.tn.gov.in/dept/school', 'Per scheme guidelines — confirm on the official application portal.', 'https://www.tn.gov.in/dept/school', 'https://www.tn.gov.in/dept/school', 'School Education Department (official confirmation awaited)', '2026-11-05T06:00:00.000Z', 'civic-lenz-web-verification', 'PENDING_VERIFICATION', NULL, 'scheme:itk'),
  ('cmw53odgu014tu310353qwu5u', 'Kudimaramathu Works', 'TN', 'cmw53odd500xju310a1muycvi', 'Community-participatory restoration of waterbodies: tanks, channels and anicuts. Status under the new government pending official confirmation.', 'Farmers and water user associations in beneficiary command areas.', 'Converged restoration works with community supervision.', 'Waterbodies across all 38 districts (launch-era figure, pending re-verification).', '2019-06-01T00:00:00.000Z', 'ACTIVE', 640, 'As per the department’s notified procedure — follow the official source link.', 'https://www.tn.gov.in/dept/pwd', 'Per scheme guidelines — confirm on the official application portal.', 'https://www.tn.gov.in/dept/pwd', 'https://www.tn.gov.in/dept/pwd', 'Public Works Department (official confirmation awaited)', '2026-11-05T06:00:00.000Z', 'civic-lenz-web-verification', 'PENDING_VERIFICATION', NULL, 'scheme:kudimaramathu'),
  ('cmw53odgv014vu310wea8rvo6', 'Chief Minister’s Comprehensive Health Insurance Scheme', 'TN', 'cmw53odd300xgu310ic9078zp', 'Cashless treatment cover for eligible families in empanelled hospitals, implemented alongside central coverage. Status under the new government pending official confirmation.', 'Income-eligible families of Tamil Nadu.', 'Cashless cover for listed procedures (₹5 lakh per family per year as notified).', 'About 1.5 crore families (launch-era figure, pending re-verification).', '2012-01-01T00:00:00.000Z', 'ACTIVE', 1600, 'As per the department’s notified procedure — follow the official source link.', 'https://www.tn.gov.in/dept/health', 'Per scheme guidelines — confirm on the official application portal.', 'https://www.tn.gov.in/dept/health', 'https://www.tn.gov.in/dept/health', 'Health & Family Welfare Department (official confirmation awaited)', '2026-11-05T06:00:00.000Z', 'civic-lenz-web-verification', 'PENDING_VERIFICATION', NULL, 'scheme:cmchis'),
  ('cmw53odgw014xu310cyqtf9ah', 'Kalaignar Kanavu Illam', 'TN', 'cmw53odd600xku310535fxuw9', 'Rural and urban housing scheme for eligible houseless families, converging central assistance. Phase-I works were in progress through 2025–26; continuation under the new government pending official confirmation.', 'Houseless eligible families per socioeconomic survey.', 'Grant assistance for constructing or completing a pucca house.', 'Phase-wise rollout in all districts.', '2024-05-01T00:00:00.000Z', 'ACTIVE', 3500, 'As per the department’s notified procedure — follow the official source link.', 'https://www.tn.gov.in/dept/rd', 'Per scheme guidelines — confirm on the official application portal.', 'https://www.tn.gov.in/dept/rd', 'https://www.tn.gov.in/dept/rd', 'RDPR Department (official confirmation awaited)', '2026-11-05T06:00:00.000Z', 'civic-lenz-web-verification', 'PENDING_VERIFICATION', NULL, 'scheme:kanavu-illam'),
  ('cmw53odgx014zu310t19diom9', 'Annan Seer Thittam', 'TN', 'cmw53odd600xku310535fxuw9', 'Marriage assistance announced in the maiden budget of the 17th Assembly government (5 Aug 2026): eligible brides receive an eight-gram gold coin (one sovereign) and a silk saree. ₹812 crore was earmarked for 2026-27.', 'Eligible brides as per the state marriage-assistance criteria notified with the budget.', '8-gram gold coin and silk saree for eligible brides.', 'To be notified with scheme guidelines.', '2026-08-05T00:00:00.000Z', 'ACTIVE', 812, 'As per the department’s notified procedure — follow the official source link.', 'https://financedept.tn.gov.in', 'Per scheme guidelines — confirm on the official application portal.', 'https://financedept.tn.gov.in', 'https://financedept.tn.gov.in', 'TN Budget 2026-27 (Budget speech, 5 Aug 2026)', '2026-11-05T06:00:00.000Z', 'civic-lenz-web-verification', 'VERIFIED', 'Announced in the 2026-27 budget; detailed guidelines expected via subsequent government orders.', 'scheme:annan-seer-thittam'),
  ('cmw53odgy0151u310vm0079xv', 'Tamil Nadu Semiconductor Ecosystem Scheme 2026', 'TN', NULL, 'Semiconductor-industry promotion scheme launched by CM C. Joseph Vijay on 16 Oct 2026 to boost investment and position Tamil Nadu as a premier semiconductor hub, comprising support for fabs, design firms and a skilled workforce pipeline.', 'Semiconductor manufacturing and design investors as per the scheme notification.', 'Investment facilitation and incentive framework for the semiconductor ecosystem.', 'Industry investors and the state’s electronics workforce.', '2026-10-16T00:00:00.000Z', 'ACTIVE', NULL, 'As per the department’s notified procedure — follow the official source link.', 'https://www.tn.gov.in/press-releases', 'Per scheme guidelines — confirm on the official application portal.', 'https://www.tn.gov.in/press-releases', 'https://www.tn.gov.in/press-releases', 'Government of Tamil Nadu (launch covered by The Hindu, 16 Oct 2026)', '2026-11-05T06:00:00.000Z', 'civic-lenz-web-verification', 'VERIFIED', NULL, 'scheme:tn-semiconductor-2026'),
  ('cmw53odgz0153u310tivp29nc', 'Women SHG credit boost 2026', 'TN', 'cmw53odd600xku310535fxuw9', 'In early November 2026 CM C. Joseph Vijay disbursed ₹3,000 crore in credit support to women self-help group members (about 26,000 beneficiaries reported) to expand livelihood enterprises.', 'Women self-help group members under state SHG programmes.', 'Credit disbursement of ₹3,000 crore to expand member enterprises.', 'About 26,000 SHG members (Nov 2026 reporting).', '2026-11-03T00:00:00.000Z', 'ACTIVE', NULL, 'As per the department’s notified procedure — follow the official source link.', 'https://www.tn.gov.in/press-releases', 'Per scheme guidelines — confirm on the official application portal.', 'https://www.tn.gov.in/press-releases', 'https://www.tn.gov.in/press-releases', 'Government of Tamil Nadu (covered by India Today / Daily Pioneer, Nov 2026)', '2026-11-05T06:00:00.000Z', 'civic-lenz-web-verification', 'VERIFIED', NULL, 'scheme:shg-credit-2026'),
  ('cmw53odh00155u31039czr139', 'PM-KISAN', 'CENTRAL', NULL, 'Pradhan Mantri Kisan Samman Nidhi — income support to all landholding farmer families, paid by the Union Ministry of Agriculture & Farmers’ Welfare.', 'Landholding farmer families (subject to the exclusion criteria in the scheme guidelines).', '₹6,000 per year in three equal instalments of ₹2,000 via DBT.', 'Nationwide farmer families (state-wise numbers on the official portal).', '2019-02-24T00:00:00.000Z', 'ACTIVE', NULL, 'Apply / self-register through the PM-KISAN portal or Common Service Centres; e-KYC mandatory.', 'https://pmkisan.gov.in', 'Per scheme guidelines — confirm on the official application portal.', 'https://pmkisan.gov.in', 'https://pmkisan.gov.in', 'Ministry of Agriculture & Farmers’ Welfare — PM-KISAN portal', '2026-11-05T06:00:00.000Z', 'civic-lenz-web-verification', 'VERIFIED', NULL, 'scheme:pm-kisan'),
  ('cmw53odh20157u310hzj6blbq', 'Ayushman Bharat PM-JAY', 'CENTRAL', NULL, 'Pradhan Mantri Jan Arogya Yojana — world’s largest government-funded health assurance scheme, converging in Tamil Nadu with the state’s comprehensive health insurance implementation.', 'Eligible families per SECC and occupational criteria; since Oct 2024 all citizens aged 70+ irrespective of income.', 'Cashless secondary and tertiary care cover of ₹5 lakh per family per year at empanelled hospitals.', 'Nationwide eligible families and all 70+ senior citizens (Vay Vandana card).', '2018-09-23T00:00:00.000Z', 'ACTIVE', NULL, 'Check eligibility and download the Ayushman card via the official portal or Ayushman App / CSC.', 'https://pmjay.gov.in', 'Per scheme guidelines — confirm on the official application portal.', 'https://pmjay.gov.in', 'https://pmjay.gov.in', 'National Health Authority — official PM-JAY portal', '2026-11-05T06:00:00.000Z', 'civic-lenz-web-verification', 'VERIFIED', NULL, 'scheme:pmjay')
INSERT INTO "Announcement" ("id", "title", "body", "category", "departmentId", "publisher", "publishedAt", "isImportant", "officialSource", "sourceName", "lastVerifiedAt", "verificationStatus", "naturalKey") VALUES
  ('cmw53odh20159u310qc947e8f', 'Government appeals for an eco-friendly Deepavali 2026', 'Press Release No.984 (3 Nov 2026): the Government of Tamil Nadu appeals to the public to celebrate Deepavali 2026 with minimal noise and air pollution, in line with Supreme Court timings on firecracker use.', 'PUBLIC_NOTICE', NULL, NULL, '2026-11-03T00:00:00.000Z', false, 'https://www.tn.gov.in/press-releases', 'tn.gov.in — Press Release No.984 (3 Nov 2026)', '2026-11-05T06:00:00.000Z', 'VERIFIED', 'ann:tn-pr-984-deepavali-2026'),
  ('cmw53odh4015bu310gmsrv6l8', '₹3,000 crore credit disbursed to women self-help group members', 'Chief Minister C. Joseph Vijay disbursed ₹3,000 crore in credit support to women SHG members (about 26,000 members reported) to expand livelihood enterprises — an early flagship welfare push of the new government.', 'SCHEME', NULL, NULL, '2026-11-03T00:00:00.000Z', true, 'https://www.tn.gov.in/press-releases', 'Government of Tamil Nadu (reported by India Today & Daily Pioneer, Nov 2026)', '2026-11-05T06:00:00.000Z', 'VERIFIED', 'ann:shg-credit-3000cr-2026'),
  ('cmw53odh5015du310wgcew0tn', '26 special POCSO courts and 4 NDPS courts ordered', 'The Government of Tamil Nadu has ordered the establishment of 26 special courts to try cases under the POCSO Act and four special courts for NDPS cases, strengthening fast-track justice (press release, 1 Nov 2026).', 'POLICY', NULL, NULL, '2026-11-01T00:00:00.000Z', true, 'https://www.tn.gov.in/press-releases', 'tn.gov.in — press release (1 Nov 2026)', '2026-11-05T06:00:00.000Z', 'VERIFIED', 'ann:tn-pocso-ndps-courts-2026'),
  ('cmw53odh5015fu3102gefd0c9', 'Tamil Nadu Semiconductor Ecosystem Scheme 2026 launched', 'CM C. Joseph Vijay launched the Semiconductor Ecosystem Scheme 2026 to boost investment and position Tamil Nadu as a premier semiconductor hub, with support for fabs, design firms and a skilled workforce pipeline.', 'SCHEME', NULL, NULL, '2026-10-16T00:00:00.000Z', true, 'https://www.tn.gov.in/press-releases', 'Government of Tamil Nadu (The Hindu, 16 Oct 2026)', '2026-11-05T06:00:00.000Z', 'VERIFIED', 'ann:tn-semiconductor-scheme-2026'),
  ('cmw53odh6015hu310ajswl0nc', 'Rajendra Vishwanath Arlekar takes full-time charge as Governor of Tamil Nadu', 'Following the October 2026 gubernatorial appointments by President Droupadi Murmu, Rajendra Vishwanath Arlekar — who had held additional charge since 12 March 2026 while Governor of Kerala — became full-time Governor of Tamil Nadu.', 'PRESS', NULL, NULL, '2026-10-13T00:00:00.000Z', false, 'https://lokbhavan.tn.gov.in', 'Lok Bhavan, Tamil Nadu / The New Indian Express (13 Oct 2026)', '2026-11-05T06:00:00.000Z', 'VERIFIED', 'ann:arlekar-fulltime-governor-2026'),
  ('cmw53odh7015ju3103ml910c1', 'By-election results: TVK wins Madurantakam and Dharapuram', 'Counting for the two assembly by-elections held for seats vacated by AIADMK MLAs who joined TVK concluded on 9 Oct 2026: TVK’s K. Maragatham Kumaravel won Madurantakam (74,048 votes) and P. Sathyabama won Dharapuram (66,841 votes, margin 9,471). Five assembly seats remain vacant.', 'PUBLIC_NOTICE', NULL, NULL, '2026-10-09T00:00:00.000Z', true, 'https://results.eci.gov.in', 'Election Commission of India — by-election results (9 Oct 2026)', '2026-11-05T06:00:00.000Z', 'VERIFIED', 'ann:eci-bypolls-oct2026'),
  ('cmw53odh9015lu3107r9zd9ei', 'Expanded Perunthalaivar Kamarajar Breakfast Scheme launched', 'CM C. Joseph Vijay launched the expansion of the breakfast scheme to students of Classes VI–VIII at an official function on 22 Sep 2026, adding about 15.30 lakh students to the programme.', 'SCHEME', NULL, NULL, '2026-09-22T00:00:00.000Z', true, 'https://www.tn.gov.in/press-releases', 'Government of Tamil Nadu (The Hindu & Deccan Herald, 22 Sep 2026)', '2026-11-05T06:00:00.000Z', 'VERIFIED', 'ann:kamarajar-breakfast-expansion-2026'),
  ('cmw53odha015nu310gn12pv9o', 'Budget 2026-27 presented — maiden budget of the 17th Assembly government', 'Finance Minister Dr. N. Marie Wilson presented the state budget for 2026-27 on 5 Aug 2026: total expenditure ₹4,72,585 crore, capital outlay ₹56,985 crore, ₹44,527 crore for school education, ₹812 crore for the new Annan Seer Thittam (8-gram gold coin and silk saree for eligible brides), gold rings for newborns and free laptops announced. A white paper on the state’s financial position was also announced.', 'POLICY', NULL, NULL, '2026-08-05T00:00:00.000Z', true, 'https://financedept.tn.gov.in', 'Finance Department — Budget Speech 2026-27 (PRS Legislative Research analysis)', '2026-11-05T06:00:00.000Z', 'VERIFIED', 'ann:tn-budget-2026-27'),
  ('cmw53odhb015pu310sadirq8s', 'Government formation: C. Joseph Vijay sworn in as 22nd Chief Minister', 'After TVK won 108 of 234 seats in the April 2026 election (counting 4 May), C. Joseph Vijay was sworn in as Chief Minister on 10 May 2026. The council of ministers was expanded to 35 members on 21–22 May 2026, with portfolios allocated with the Governor’s approval.', 'PRESS', NULL, NULL, '2026-05-10T00:00:00.000Z', true, 'https://www.tn.gov.in/ministers', 'Government of Tamil Nadu — Council of Ministers', '2026-11-05T06:00:00.000Z', 'VERIFIED', 'ann:vijay-cm-swornin-2026'),
  ('cmw53odhs015ru3100khgzg73', '2026 Legislative Assembly election held across 234 constituencies', 'Elections to the 17th Tamil Nadu Legislative Assembly were held on 23 April 2026 with counting on 4 May 2026: TVK 108 seats (35.07% votes), DMK 59 (24.28%), AIADMK 47 (21.30%), with the balance to allies and others. Full constituency-wise results are on the ECI portal.', 'PUBLIC_NOTICE', NULL, NULL, '2026-05-04T00:00:00.000Z', true, 'https://results.eci.gov.in', 'Election Commission of India — 2026 TN general election results', '2026-11-05T06:00:00.000Z', 'VERIFIED', 'ann:eci-tn-2026-results')
INSERT INTO "CalendarEvent" ("id", "title", "description", "startsAt", "endsAt", "location", "type", "organizer", "verificationStatus", "sourceNote") VALUES
  ('cmw53odhv015su310h043o4rd', 'First Session of the 17th Legislative Assembly', 'The first session of the newly constituted 17th Tamil Nadu Legislative Assembly sat from 11 May to 8 Sep 2026 (28 sitting days; 13 Bills passed, 9 government resolutions and 17 Rule 110 announcements).', '2026-05-11T10:00:00.000Z', '2026-09-08T17:00:00.000Z', 'Fort St George, Chennai', 'ASSEMBLY_SESSION', 'Government of Tamil Nadu', 'VERIFIED', 'Session record as per the Tamil Nadu Legislative Assembly (tnla.neva.gov.in) and assembly reporting.'),
  ('cmw53odhw015tu310fsdfrtct', 'November 2026 session of the Legislative Assembly', 'The assembly’s session calendar lists a session in November 2026. Exact dates to be confirmed from the official session calendar.', '2026-11-16T10:00:00.000Z', NULL, 'Fort St George, Chennai', 'ASSEMBLY_SESSION', 'Government of Tamil Nadu', 'PENDING_VERIFICATION', 'Session calendar at tnla.neva.gov.in lists a November 2026 session; exact sitting dates pending confirmation. Placeholder date shown until verified.'),
  ('cmw53odhx015uu310m88aqkf5', 'By-elections to vacant assembly constituencies', 'By-elections to the remaining vacant seats (Tiruchirappalli East, Perundurai, Ambasamudram, Viralimalai, Karur) per ECI notifications. Madurantakam and Dharapuram were filled on 9 Oct 2026.', '2026-11-25T08:00:00.000Z', NULL, 'Respective constituencies', 'ELECTION', 'Government of Tamil Nadu', 'PENDING_VERIFICATION', 'Polling dates for the five vacant ACs pending the latest ECI notification (earlier process reported to be affected by litigation). Placeholder date shown until verified.'),
  ('cmw53odhy015vu3108ucd79xz', 'Monthly grievance day hearing', 'Collectorate grievance day — petitioners with registration numbers are heard by the District Collector.', '2026-11-17T09:30:00.000Z', '2026-11-17T13:00:00.000Z', 'All District Collectorates', 'PUBLIC_HEARING', 'Government of Tamil Nadu', 'PENDING_VERIFICATION', 'Grievance day is a standing monthly practice; confirm the exact date with the respective district collectorate. Placeholder date shown until verified.'),
  ('cmw53odhy015wu310mxiae5bz', 'White paper on the state’s financial position — release', 'The government has announced a white paper detailing Tamil Nadu’s financial position. Release date to be confirmed.', '2026-11-30T11:00:00.000Z', NULL, 'Secretariat, Chennai', 'DEADLINE', 'Government of Tamil Nadu', 'PENDING_VERIFICATION', 'Announced by the Finance Department (2026-27 budget communications); release date pending official confirmation. Placeholder date shown until verified.')
