INSERT INTO "Complaint" ("id", "ticketNo", "title", "description", "category", "priority", "status", "districtId", "citizenName", "citizenContact", "wardOrArea", "assignedDepartmentId", "assignedTo", "slaDueAt", "resolutionNote", "satisfaction", "isPublic", "createdAt", "updatedAt") VALUES
  ('cmw53odj2018ou310iuu7b3r4', 'CL-2025-000118', 'Sewage overflow near corporation school', 'Untreated sewage is overflowing on the street adjoining the corporation school for three weeks. Children walk through stagnant water to reach the school gate. Request urgent desilting of the blocked line and disinfection.', 'SANITATION', 'HIGH', 'IN_PROGRESS', 'cmw53ocvn0015u310cwarmae0', 'R. Lakshmi', '+91-XXXXX-XX18', 'Ward 173, Kodambakkam zone', 'cmw53odd700xmu310309m5epc', 'Zonal Engineer — Kodambakkam', '2025-11-08T00:00:00.000Z', NULL, NULL, true, '2025-10-20T09:30:00.000Z', '2026-11-06T14:59:11.871Z'),
  ('cmw53odj6018wu3105vbzwmyo', 'CL-2025-000104', 'Street lights not working for a month', 'Nine of eleven streetlights in the lane are non-functional after the last spell of rain. Two-wheelers skid at night; residents request immediate replacement of fittings.', 'ELECTRICITY', 'MEDIUM', 'RESOLVED', 'cmw53ocvo0017u310ufr4fnr8', 'S. Karthik', '+91-XXXXX-XX04', 'Ward 28, North zone', 'cmw53odd700xmu310309m5epc', 'AE — Street Lights', '2025-10-30T00:00:00.000Z', 'All fittings replaced with LED luminaires and wiring repaired. Verified during night inspection on 28 Oct.', 5, true, '2025-10-06T09:30:00.000Z', '2026-11-06T14:59:11.875Z'),
  ('cmw53odja0196u310wkcjgjb4', 'CL-2025-000097', 'Drinking water tanker not reaching street 4', 'Tanker schedule shows daily supply but tankers have not entered street 4 for eleven days. Residents including elderly persons are buying water.', 'WATER', 'CRITICAL', 'ESCALATED', 'cmw53ocw5002tu310letgwgtr', 'Fathima A.', '+91-XXXXX-XX97', 'Ward 12', 'cmw53odd700xmu310309m5epc', 'Executive Engineer — TWAD', '2025-11-02T00:00:00.000Z', NULL, NULL, true, '2025-10-19T09:30:00.000Z', '2026-11-06T14:59:11.878Z'),
  ('cmw53odjd019eu310euvuy5tj', 'CL-2025-000089', 'Potholes on school road causing accidents', 'Two-wheelers are skidding on the pothole-ridden stretch near the government school. Two minor falls reported this month. Request cold-mix patchwork immediately and re-tarring after monsoon.', 'ROAD', 'HIGH', 'ACKNOWLEDGED', 'cmw53ocvu001ru310jg2gydfm', 'P. Muthu', '+91-XXXXX-XX89', 'Ward 44', 'cmw53odd500xju310a1muycvi', 'Section Officer — Roads', '2025-11-06T00:00:00.000Z', NULL, NULL, true, '2025-10-11T09:30:00.000Z', '2026-11-06T14:59:11.882Z'),
  ('cmw53odjg019ku310xue9wmr3', 'CL-2025-000076', 'Demand for bribe at building plan approval', 'An intermediary at the local body office demanded ₹15,000 to expedite building plan approval and hinted approval will otherwise be delayed. Requesting confidential enquiry and action.', 'CORRUPTION', 'CRITICAL', 'IN_PROGRESS', 'cmw53ocw7002zu31011zquag9', 'Anonymous', '+91-XXXXX-XX76', 'Local body — Vellore', 'cmw53odd900xpu31024f3c2bt', 'Vigilance Cell', '2025-11-15T00:00:00.000Z', NULL, NULL, true, '2025-10-18T09:30:00.000Z', '2026-11-06T14:59:11.884Z'),
  ('cmw53odji019qu310td16omkc', 'CL-2025-000061', 'PHC without doctor on Tuesdays', 'The primary health centre in our block functions without a medical officer on Tuesdays for the past month, affecting the weekly maternal check-up camp.', 'HEALTH', 'HIGH', 'RESOLVED', 'cmw53ocw3002nu310gb59vfhj', 'J. steffen', '+91-XXXXX-XX61', 'Block PHC', 'cmw53odd300xgu310ic9078zp', 'Deputy Director — Health Services', '2025-10-20T00:00:00.000Z', 'Medical officer posting regularised and a standby roster notified. Camp schedule restored.', 4, true, '2025-10-03T09:30:00.000Z', '2026-11-06T14:59:11.886Z'),
  ('cmw53odjj019yu3109vvgxw9x', 'CL-2025-000052', 'Anganwadi building roof leak', 'Roof of the anganwadi building leaks during rain; children’s activities shifted to the community hall. Request roof repair with waterproofing.', 'OTHER', 'MEDIUM', 'IN_PROGRESS', 'cmw53ocw0002fu310w6hdun62', 'K. Valarmathi', '+91-XXXXX-XX52', 'Village panchayat 9', 'cmw53odd600xku310535fxuw9', 'BDO — Block 9', '2025-11-12T00:00:00.000Z', NULL, NULL, true, '2025-10-14T09:30:00.000Z', '2026-11-06T14:59:11.888Z'),
  ('cmw53odjm01a4u310saa00mrt', 'CL-2025-000047', 'Mid-day meal quality complaint', 'Eggs supplied under the nutrition menu have been stale on two days this week. Request inspection and quality check of supplier consignments.', 'EDUCATION', 'HIGH', 'SUBMITTED', 'cmw53ocvr001du3102c089pzd', 'Name withheld', '+91-XXXXX-XX47', 'GHS — Block 5', 'cmw53odd400xhu310jfy6ee30', NULL, '2025-11-04T00:00:00.000Z', NULL, NULL, true, '2025-10-09T09:30:00.000Z', '2026-11-06T14:59:11.890Z'),
  ('cmw53odjo01a8u310jy1o5le8', 'CL-2025-000033', 'Encroachment blocking stormwater drain', 'Shops have extended ramps over the stormwater drain causing waterlogging in the lane during rains. Request enforcement and restoration of drain section.', 'SANITATION', 'MEDIUM', 'REJECTED', 'cmw53ocvz0029u310eazast1v', 'V. Suresh', '+91-XXXXX-XX33', 'Ward 31', 'cmw53odd700xmu310309m5epc', 'Town Planning', NULL, 'Reopening of drain verified as completed under an earlier works order; lane-level waterlogging traced to private plot grading outside corporation scope. Advised applicant of the correct forum.', 2, true, '2025-10-15T09:30:00.000Z', '2026-11-06T14:59:11.892Z'),
  ('cmw53odjq01aeu31011iv5x9h', 'CL-2025-000021', 'Bus shelter damaged and unsafe', 'The bus shelter on the route collapsed partially in the last storm; the roof sheet hangs loose over waiting passengers.', 'ROAD', 'HIGH', 'RESOLVED', 'cmw53ocvr001fu310ohkzejyd', 'M. Gowtham', '+91-XXXXX-XX21', 'Route 12 stop', 'cmw53odd800xnu3106hqld57c', 'Depot Manager', '2025-10-18T00:00:00.000Z', 'Shelter dismantled and rebuilt with new roofing; safety inspection completed.', 5, true, '2025-10-03T09:30:00.000Z', '2026-11-06T14:59:11.894Z')
