  ('cmw53oddm00yfu310aiduvtm8', 'Rajendra Vishwanath Arlekar', 'GOVERNOR', 'Governor of Tamil Nadu', NULL, NULL, 'STATE', 'cmw53ocvc000mu31008etsr9h', NULL, NULL, NULL, NULL, 'Governor of Tamil Nadu', NULL, '2026 – present', 'https://lokbhavan.tn.gov.in', 'Lok Bhavan (Raj Bhavan), Tamil Nadu', '2026-03-12T00:00:00.000Z', NULL, '2026-11-05T06:00:00.000Z', 'civic-lenz-web-verification', 'CURRENT', 'VERIFIED', 'Assumed additional charge as Governor of Tamil Nadu on 12 Mar 2026 (while Governor of Kerala) after R. N. Ravi’s transfer; appointed full-time Governor in the October 2026 gubernatorial reshuffle and took full-time charge in mid-Oct 2026.', '2026-11-06T14:59:11.675Z', '2026-11-06T14:59:11.675Z'),
  ('cmw53oddp00ylu310w9uvhqq5', 'R. N. Ravi', 'GOVERNOR', 'Former Governor of Tamil Nadu (26th)', NULL, NULL, 'STATE', 'cmw53ocvc000mu31008etsr9h', NULL, NULL, NULL, NULL, 'Former Governor of Tamil Nadu (26th)', NULL, '2021 – 2026', 'https://lokbhavan.tn.gov.in', 'Lok Bhavan (Raj Bhavan), Tamil Nadu / Union Home Ministry notification', '2021-09-18T00:00:00.000Z', '2026-03-12T00:00:00.000Z', '2026-11-05T06:00:00.000Z', 'civic-lenz-web-verification', 'FORMER', 'VERIFIED', 'Tenure ended on transfer as Governor of West Bengal (announced 5 Mar 2026).', '2026-11-06T14:59:11.677Z', '2026-11-06T14:59:11.677Z'),
  ('cmw53odds00yru3107uch24l4', 'C. Joseph Vijay', 'CHIEF_MINISTER', 'Chief Minister of Tamil Nadu (22nd)', 'Tamilaga Vettri Kazhagam', 'TVK', 'STATE', 'cmw53ocvc000mu31008etsr9h', 'cmw53ocvn0015u310cwarmae0', 'ASSEMBLY', 'Perambur', NULL, 'Chief Minister of Tamil Nadu (22nd)', NULL, '2026 – present', 'https://www.tn.gov.in/ministers', 'Government of Tamil Nadu — Council of Ministers', '2026-05-10T00:00:00.000Z', NULL, '2026-11-05T06:00:00.000Z', 'civic-lenz-web-verification', 'CURRENT', 'VERIFIED', 'Sworn in as the 22nd Chief Minister on 10 May 2026 after TVK won 108 of 234 seats in the April 2026 election (counting 4 May). Won both Perambur and Tiruchirappalli East; retained Perambur and resigned Tiruchirappalli East. Portfolio allocation approved by Governor Arlekar (May 2026). Party founded 2 Feb 2024; party flag launched 22 Aug 2024.', '2026-11-06T14:59:11.680Z', '2026-11-06T14:59:11.680Z'),
  ('cmw53oddv00yxu310mplqehpo', 'Udhayanidhi Stalin', 'LEADER_OF_OPPOSITION', 'Leader of the Opposition, Tamil Nadu Legislative Assembly (19th)', 'Dravida Munnetra Kazhagam', 'DMK', 'STATE', 'cmw53ocvc000mu31008etsr9h', 'cmw53ocvn0015u310cwarmae0', 'ASSEMBLY', 'Chepauk-Thiruvallikeni', NULL, 'Leader of the Opposition, Tamil Nadu Legislative Assembly (19th)', '#b91c1c', '2026 – present', 'https://www.assembly.tn.gov.in', 'Tamil Nadu Legislative Assembly', '2026-05-11T00:00:00.000Z', NULL, '2026-11-05T06:00:00.000Z', 'civic-lenz-web-verification', 'CURRENT', 'VERIFIED', 'Took oath as Leader of the Opposition on 11 May 2026 after the DMK won 59 seats. Previously Deputy Chief Minister (Dec 2024 – May 2026) in the DMK government; re-elected from Chepauk-Thiruvallikeni in April 2026.', '2026-11-06T14:59:11.683Z', '2026-11-06T14:59:11.683Z'),
